INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dQh4DBD6sJ5', 4, '{"title":"第20300820条・痈疽第八十一","description":"<p>6、发于肩及臑。名曰疵痈。其状赤黑。急治之。此令人汗出至足。不害五藏。痈发四五日。逞焫之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300820,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '6、发于肩及臑。名曰疵痈。其状赤黑。急治之。此令人汗出至足。不害五藏。痈发四五日。逞焫之。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mVLk6vCgLpp', 4, '{"title":"第20300821条・痈疽第八十一","description":"<p>7、发于腋下赤坚者。名曰米疽。治之以砭石。欲细而长。疏砭之。涂以豕膏。六日已。勿裹之。其痈坚而不溃者。为马刀挟瘿。急治之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300821,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '7、发于腋下赤坚者。名曰米疽。治之以砭石。欲细而长。疏砭之。涂以豕膏。六日已。勿裹之。其痈坚而不溃者。为马刀挟瘿。急治之。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WQMJqozvT2h', 4, '{"title":"第20300822条・痈疽第八十一","description":"<p>8、发于胸。名曰井疽。其状如大豆。三四日起。不早治。下入腹。不治。七日死矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300822,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '8、发于胸。名曰井疽。其状如大豆。三四日起。不早治。下入腹。不治。七日死矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sK3kQ6x9Enn', 4, '{"title":"第20300823条・痈疽第八十一","description":"<p>9、发于膺。名曰甘疽。色青。其状如谷实𦸈𧁾。常苦寒热。急治之。去其寒热。十岁死。死后出脓。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300823,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '9、发于膺。名曰甘疽。色青。其状如谷实𦸈𧁾。常苦寒热。急治之。去其寒热。十岁死。死后出脓。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eUgUyCkltRS', 4, '{"title":"第20300824条・痈疽第八十一","description":"<p>10、发于胁。名曰败疵。败疵者。女子之病也。灸之。其病大痈脓。治之。其中乃有生肉。大如赤小豆。坐陵翘草根各一升。以水一斗六升煮之。竭为取三升。则强饮厚衣。坐于釜上。令汗出至足已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300824,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '10、发于胁。名曰败疵。败疵者。女子之病也。灸之。其病大痈脓。治之。其中乃有生肉。大如赤小豆。坐陵翘草根各一升。以水一斗六升煮之。竭为取三升。则强饮厚衣。坐于釜上。令汗出至足已。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ukkWEVb5Tkm', 4, '{"title":"第20300825条・痈疽第八十一","description":"<p>11、发于股胫。名曰股胫疽。其状不甚变。而痈脓搏骨。不急治。三十日死矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300825,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '11、发于股胫。名曰股胫疽。其状不甚变。而痈脓搏骨。不急治。三十日死矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TAv8GPmEjGf', 4, '{"title":"第20300826条・痈疽第八十一","description":"<p>12、发于尻。名曰锐疽。其状赤坚大。急治之。不治。三十日死矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300826,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '12、发于尻。名曰锐疽。其状赤坚大。急治之。不治。三十日死矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5YBTPQAy3Le', 4, '{"title":"第20300827条・痈疽第八十一","description":"<p>13、发于股阴。名曰赤施。不急治。六十日死。在两股之内。不治。十日而当死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300827,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '13、发于股阴。名曰赤施。不急治。六十日死。在两股之内。不治。十日而当死。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yXLEzAJO1Fj', 4, '{"title":"第20300828条・痈疽第八十一","description":"<p>14、发于膝。名曰疵痈。其状大。痈色不变。寒热。如坚石。勿石。石之者死。须其柔。乃石之者。生。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300828,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '14、发于膝。名曰疵痈。其状大。痈色不变。寒热。如坚石。勿石。石之者死。须其柔。乃石之者。生。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CB2EO58Lfgh', 4, '{"title":"第20300829条・痈疽第八十一","description":"<p>15、诸痈疽之发于节而相应者。不可治也。发于阳者。百日死。发于阴者。三十日死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300829,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '15、诸痈疽之发于节而相应者。不可治也。发于阳者。百日死。发于阴者。三十日死。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vaGniclyyvl', 4, '{"title":"第20300830条・痈疽第八十一","description":"<p>16、发于胫。名曰兔啮。其状赤至骨。急治之。不治害人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300830,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '16、发于胫。名曰兔啮。其状赤至骨。急治之。不治害人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RrFGZ8vuWDr', 4, '{"title":"第20300831条・痈疽第八十一","description":"<p>17、发于内踝。名曰走缓。其状痈也。色不变。数石其输。而止其寒热。不死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300831,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '17、发于内踝。名曰走缓。其状痈也。色不变。数石其输。而止其寒热。不死。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0QC3way42Sw', 4, '{"title":"第20300832条・痈疽第八十一","description":"<p>18、发于足上下。名曰四淫。其状大痈。急治之。百日死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300832,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '18、发于足上下。名曰四淫。其状大痈。急治之。百日死。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6bBMduUpsdl', 4, '{"title":"第20300833条・痈疽第八十一","description":"<p>19、发于足傍。名曰厉痈。其状不大。初如小指。发。急治之。去其黑者。不消辄益。不治。百日死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300833,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '19、发于足傍。名曰厉痈。其状不大。初如小指。发。急治之。去其黑者。不消辄益。不治。百日死。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8IawKDEXpeb', 4, '{"title":"第20300834条・痈疽第八十一","description":"<p>20、发于足指。名脱痈。其状赤黑。死不治。不赤黑。不死。不衰。急斩之。不则死矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300834,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '20、发于足指。名脱痈。其状赤黑。死不治。不赤黑。不死。不衰。急斩之。不则死矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hJS69RvRbYA', 4, '{"title":"第20300835条・痈疽第八十一","description":"<p>21、黄帝曰。夫子言痈疽。何以别之。岐伯曰。营卫稽留于经脉之中。则血泣而不行。不行则卫气从之而不通。壅遏而不得行。故热。大热不止。热胜。则肉腐。肉腐则为脓。然不能陷。骨髓不为焦枯。五藏不为伤。故命曰痈。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300835,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '21、黄帝曰。夫子言痈疽。何以别之。岐伯曰。营卫稽留于经脉之中。则血泣而不行。不行则卫气从之而不通。壅遏而不得行。故热。大热不止。热胜。则肉腐。肉腐则为脓。然不能陷。骨髓不为焦枯。五藏不为伤。故命曰痈。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N0xTl8CjkPi', 4, '{"title":"第20300836条・痈疽第八十一","description":"<p>22、黄帝曰。何谓疽。岐伯曰。热气淳盛。下陷肌肤。筋髓枯。内连五藏。血气竭。当其痈下。筋骨良肉皆无余。故命曰疽。疽者。上之皮夭以坚。上如牛领之皮。痈者。其皮上薄以泽。此其候也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300836,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '22、黄帝曰。何谓疽。岐伯曰。热气淳盛。下陷肌肤。筋髓枯。内连五藏。血气竭。当其痈下。筋骨良肉皆无余。故命曰疽。疽者。上之皮夭以坚。上如牛领之皮。痈者。其皮上薄以泽。此其候也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
